{
  "title": "Build Your First Web Page in 10 Minutes",
  "summary": "The presenter makes a simple personal page with a heading, a paragraph and a list, then colours the heading with CSS.",
  "chapters": [
    {
      "title": "The HTML page",
      "start": 0,
      "end": 245
    },
    {
      "title": "Adding style",
      "start": 245,
      "end": 410
    }
  ],
  "segments": [
    {
      "start": 0,
      "end": 35,
      "chapter": "The HTML page",
      "action": "Introduces the project and shows the finished page.",
      "file": "",
      "code": ""
    },
    {
      "start": 35,
      "end": 120,
      "chapter": "The HTML page",
      "action": "Creates index.html and types the basic page skeleton.",
      "file": "index.html",
      "code": "<!DOCTYPE html>\n<html>\n  <head>\n    <title>My Page</title>\n  </head>\n  <body>\n  </body>\n</html>"
    },
    {
      "start": 120,
      "end": 245,
      "chapter": "The HTML page",
      "action": "Adds a big heading, a paragraph and a list of hobbies inside body.",
      "file": "index.html",
      "code": "<h1>Hello, I'm Alex</h1>\n<p>I like making things.</p>\n<ul>\n  <li>Music</li>\n  <li>Football</li>\n</ul>"
    },
    {
      "start": 245,
      "end": 330,
      "chapter": "Adding style",
      "action": "Creates style.css and links it from the head.",
      "file": "index.html",
      "code": "<link rel=\"stylesheet\" href=\"style.css\">"
    },
    {
      "start": 330,
      "end": 410,
      "chapter": "Adding style",
      "action": "Colours the heading purple.",
      "file": "style.css",
      "code": "h1 {\n  color: purple;\n}"
    }
  ]
}
